{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    # Compute mutual reachability distance for each edge
    mreach_edges = []
    for u, v, d in distances:
        mrd = max(core_distance[u], core_distance[v], d)
        mreach_edges.append((u, v, mrd))

    # Sort edges by mutual reachability distance (Kruskal's MST)
    mreach_edges.sort(key=lambda e: e[2])

    # Union-Find with path compression and union by rank
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    mst_edges = []
    total_weight = 0.0

    for u, v, w in mreach_edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
"}
